//! `validate_kind` — per-method record of the kit module.

use super::KIT_KINDS;

pub(crate) fn validate_kind(kind: &str) -> Result<(), String> {
    if KIT_KINDS.contains(&kind) {
        Ok(())
    } else {
        Err(format!("invalid kit kind '{kind}' — want one of: {}", KIT_KINDS.join(" | ")))
    }
}
